self.pink_battle_dialogue3 = S.stringsetloc(self, other, "Arrgh^1, that&stupid bug&said it was&FUCHSIA!!/%", "obj_pink_enemy_slash_Create_0_gml_120_0");
self.pink_battle_dialogue4 = S.stringsetloc(self, other, "Well^1, no&matter!&You're&trapped now!/%", "obj_pink_enemy_slash_Create_0_gml_121_0");
self.pink_battle_dialogue5 = S.stringsetloc(self, other, "A little floral tea &will have you tickled &pink^1! Pink^1! PINK!!!/%", "obj_pink_enemy_slash_Create_0_gml_122_0");
self.pink_battle_dialogue6 = S.stringsetloc(self, other, "Stop..^1. looking!/%", "obj_pink_enemy_slash_Create_0_gml_125_0");
self.pink_battle_dialogue7 = S.stringsetloc(self, other, "Stop making my&body purr^1, you&jerks!/%", "obj_pink_enemy_slash_Create_0_gml_126_0");
self.pink_battle_dialogue8 = S.stringsetloc(self, other, "Mew.&Mew!&MEW!/%", "obj_pink_enemy_slash_Create_0_gml_127_0");
self.pink_battle_dialogue9 = S.stringsetloc(self, other, "What!^1? WHAT do&I look like,&a pincushion!?/%", "obj_pink_enemy_slash_Create_0_gml_128_0");
self.pink_battle_dialogue6b = S.stringsetloc(self, other, "S..^1. stop&LOOKING at them!/%", "obj_pink_enemy_slash_Create_0_gml_130_0");
self.pink_battle_dialogue6c = S.stringsetloc(self, other, "Stop making my&body purr^1, you&jerks!/%", "obj_pink_enemy_slash_Create_0_gml_131_0");
self.pink_battle_dialogue6d = S.stringsetloc(self, other, "Stop.&STOP!&STOP!!!!/%", "obj_pink_enemy_slash_Create_0_gml_132_0");
self.pink_battle_dialogue6e = S.stringsetloc(self, other, "Where are&my knives!?/%", "obj_pink_enemy_slash_Create_0_gml_133_0");
