self.pink_battle_dialogue11 = S.stringsetloc(self, other, "Figure out how&to move^1, see if&I care^1, MEW!/%", "obj_pink_enemy_slash_Create_0_gml_143_0");
self.pink_battle_dialogue12 = S.stringsetloc(self, other, "Now that you're&PURPLE^1, you're&restricted in my&FELINE WEB!/%", "obj_pink_enemy_slash_Create_0_gml_145_0");
self.pink_battle_dialogue13 = S.stringsetloc(self, other, "Before this body,&I was NOBODY!&A ghost^1! A NOTHING!/%", "obj_pink_enemy_slash_Create_0_gml_146_0");
